import numpy as np
from scipy.optimize import least_squares
y=dA_dt
Aa=np.abs(A)
def F(p): return (p[0]+p[1]/t+p[2]*t+p[3]*np.exp(-t))
def f1(p):
    S=1-np.exp(-np.abs(p[5])*Aa**p[6])
    return -F(p)*(1+p[4]*S+p[7]*S**2)
def f3(p):
    return -F(p)+(p[4]+p[5]*t+p[6]*t**2)*(1-np.exp(-np.abs(p[7]+p[8]*t)*Aa**p[9]))
